/usr/bin/bash -lc "PYTHONPATH=source SKRF_PLOT_ENV=off python - <<'PY'
import numpy as np, skrf as rf
rng=np.random.default_rng(22)

def xmat(z1,z2,sd):
 z1,z2=np.broadcast_arrays(np.asarray(z1,complex),np.asarray(z2,complex)); d=z1+z2;x=np.empty((z1.size,2,2),complex)
 if sd=='power':
  dc=d.conj();x[:,0,0]=(z2.conj()-z1)/dc;x[:,1,1]=(z1.conj()-z2)/dc;x[:,0,1]=x[:,1,0]=2*np.sqrt(z1.real*z2.real)/dc
 elif sd=='pseudo':
  u1=np.sqrt(z1.real)/abs(z1);u2=np.sqrt(z2.real)/abs(z2);x[:,0,0]=(z2-z1)/d;x[:,1,1]=(z1-z2)/d;x[:,0,1]=2*u1*z1/(u2*d);x[:,1,0]=2*u2*z2/(u1*d)
 else:
  x[:,0,0]=(z2-z1)/d;x[:,1,1]=(z1-z2)/d;x[:,0,1]=x[:,1,0]=2*np.sqrt(z1*z2)/d
 return x

def inner(s,k,l,x):
 ii=[k,l];ee=[i for i in range(s.shape[1]) if i not in ii]
 return s[:,ee][:,:,ee]+s[:,ee][:,:,ii]@np.linalg.solve(np.eye(2)-x@s[:,ii][:,:,ii],x@s[:,ii][:,:,ee])
def conn(a,k,b,l,sd):
 s=np.zeros((len(a),a.nports+b.nports,a.nports+b.nports),complex);s[:,:a.nports,:a.nports]=a.s;s[:,a.nports:,a.nports:]=b.s
 return inner(s,k,a.nports+l,xmat(a.z0[:,k],b.z0[:,l],sd))
for na,nb,k,l in [(3,4,1,2),(2,2,1,0),(5,1,3,0)]:
 nf=9;f=np.arange(nf)
 sa=(rng.normal(size=(nf,na,na))+1j*rng.normal(size=(nf,na,na)))*.08
 sb=(rng.normal(size=(nf,nb,nb))+1j*rng.normal(size=(nf,nb,nb)))*.08
 A0=rf.Network(f=f,s=sa,z0=50);B0=rf.Network(f=f,s=sb,z0=50);E0=rf.connect(A0,k,B0,l)
 for sd in ['power','pseudo','traveling']:
  za=40+rng.random((nf,na))*30+1j*(rng.random((nf,na))-.5)*20
  zb=40+rng.random((nf,nb))*30+1j*(rng.random((nf,nb))-.5)*20
  A=A0.copy();B=B0.copy();A.renormalize(za,sd);B.renormalize(zb,sd)
  gout=conn(A,k,B,l,sd)
  zout=np.hstack((np.delete(za,k,1),np.delete(zb,l,1)))
  E=E0.copy();E.renormalize(zout,sd)
  print(na,nb,sd,abs(gout-E.s).max())
# inner 4-port: original then ref external
nf=8;n=4;s=(rng.normal(size=(nf,n,n))+1j*rng.normal(size=(nf,n,n)))*.05;N0=rf.Network(f=np.arange(nf),s=s,z0=50);E0=rf.innerconnect(N0,1,3)
for sd in ['power','pseudo','traveling']:
 z=45+rng.random((nf,n))*20+1j*(rng.random((nf,n))-.5)*12;N=N0.copy();N.renormalize(z,sd);x=xmat(z[:,1],z[:,3],sd);g=inner(N.s,1,3,x);E=E0.copy();E.renormalize(z[:,[0,2]],sd);print('inner',sd,abs(g-E.s).max())
PY"
